const jobs = new Map();
let workerTail = Promise.resolve();
export const CRAPS_REPLAY_WORKER_TIMEOUT_MS = 30_000;
const CUSTOM = 1n << 40n;
const slotKey = slot => `0x${slot.toString(16).padStart(64, '0')}`;
/**
 * The daily jackpot battle: a craps-table field at remainder 6 (`_slotOf(day, 5)`) or, on a day
 * with no paid field, the detached remainder 7. It is never armed; its word, terms and
 * awarded-seat count live in `_jackpotRounds[slot]` and `JackpotBattleStarted`. Its key is its slot.
 */
const isJackpotSlot = slot => slot < CUSTOM && slot % 8n >= 6n;

/**
 * The fee a jackpot round's high seats ride, for the engine's `jackpotHighExtra(highMult,
 * multiplierBps, entryPrice)` (`_slotWindow`: `(highMult - 1) * r.entryPrice * r.multiplierBps /
 * 20_000`). Each round stores its own fee in `_jackpotRounds[slot].entryPrice` (6,000 / 8,000 /
 * 10,000 whole FLIP, what `jackpotEntryPriceOf(slot)` returns).
 */
export function crapsJackpotEntryPrice(round) {
  return BigInt(round?.entryPrice ?? 0);
}
// CrapsBattle's boost rung for a battle: a draw off (settlement word, battle key), in quarter units
// (1/4/40/400 for the .25x/1x/10x/100x rungs). Null until the word has landed.
const BOOST_TAG = 0x426f6f7374n;
const wordHex = value => BigInt(value).toString(16).padStart(64, '0');
export function boostQuarterMultiple(battleKey, word) {
  if (word == null || BigInt(word) === 0n) return null;
  const roll = BigInt(keccak256(`0x${wordHex(29n)}${wordHex(word)}${wordHex(battleKey)}`)) % 1000n;
  return roll < 768n ? 1n : roll < 976n ? 4n : roll < 996n ? 40n : 400n;
}
const battleKey = value => {
  if (!/^0x[0-9a-f]{64}$/i.test(value)) throw new ChainDataError('Invalid battle key.', 'INVALID_REQUEST');
  return value.toLowerCase();
};

/**
 * Scheduled bets live in 64 physical day banks and three 72-bit seats pack into one storage word.
 * The storage key keeps the slot's low nine bits (day mod 64) and the seat's word index; the word
 * carries the exact day in bits 216..239, and a word whose day is not `id >> 67` belongs to a later
 * day and reads as no bet. Custom bets keep their full slot. Mirrors CrapsBattleStorage._loadBet.
 */
export function crapsBetStorageKey(id) {
  id = BigInt(id);
  const slot = id >> 64n, seat = id & ((1n << 64n) - 1n);
  return ((slot < CUSTOM ? slot & 511n : slot) << 64n) | (seat === 0n ? 0n : 1n + (seat - 1n) / 3n);
}
export function crapsBetFromStorage(id, stored) {
  id = BigInt(id); const word = BigInt(stored ?? 0);
  const seat = id & ((1n << 64n) - 1n);
  if (!seat || id >> 64n < CUSTOM && ((word >> 216n) & 0xffffffn) !== id >> 67n) return 0n;
  return (word >> (((seat - 1n) % 3n) * 72n)) & ((1n << 72n) - 1n);
}
export async function crapsBetWord(s, id) {
  let word = crapsBetFromStorage(id, await s.field('CRAPS', '_bets', crapsBetStorageKey(id)));
  const slot = BigInt(id) >> 64n, seat = BigInt(id) & ((1n << 64n) - 1n);
  if (word && slot < CUSTOM && (slot & 7n) >= 6n) {
    const round = await crapsField(s, '_jackpotRounds', slot);
    const dayCount = (slot & 7n) === 7n ? 0n : BigInt(await crapsField(s, '_dayTickets', slot & ~7n)) & 0xffffffffn;
    if (round.requestDay && seat + dayCount > BigInt(round.paidCount)) word |= 1n << 72n;
  }
  return word;
}
/**
 * A custom battle's packed terms (CrapsBattleStorage `_customBattle` / CrapsBattleCreated.terms):
 * played bits 0..27, bankMult 28..32, goalMult 33..42, stakeUnits 43..60 (100-FLIP granules),
 * closeTime 61..100, the multi-entry bit 101 and the high-roller multiple 102..109 (0..255).
 * Money fields are whole FLIP counts.
 */
export function decodeCustomBattleTerms(word) {
  const c = BigInt(word ?? 0);
  return { played: c & 0xfffffffn, bankMult: (c >> 28n) & 31n, goalMult: (c >> 33n) & 1023n, stakeUnits: (c >> 43n) & 0x3ffffn,
    closeTime: Number((c >> 61n) & 0xffffffffffn), multiEntry: Boolean((c >> 101n) & 1n),
    highMultiple: Number((c >> 102n) & 255n) };
}

// Only a requested battle is materialized. The worker has no RPC access and
// cannot publish unless every reconstructed won amount matches settlement.
export async function loadReplayInputs(s, key, signal) {
  const latest = { blockNumber: s.block.number, logIndex: Number.MAX_SAFE_INTEGER };
  const jackpot = isJackpotSlot(BigInt(key));
  // A window is found by its arm; the jackpot battle is never armed, and its field starts (word,
  // terms and awarded seats frozen) at `JackpotBattleStarted`.
  const start = (await previousEvents(s.client, 'CRAPS', jackpot ? 'JackpotBattleStarted' : 'CrapsBonusArmed', latest,
    { filters: jackpot ? { slot: BigInt(key) } : { battleKey: key }, signal })).at(-1);
  if (!start) throw new ChainDataError(jackpot ? 'This jackpot battle has not drawn its field.' : 'This battle has not closed for entry.', 'REPLAY_PENDING');
  const arm = jackpot ? null : start;
  const slot = BigInt(start.args.slot); const custom = slot >= CUSTOM; const day = Number(slot / 8n);
  const final = (await eventFacts(s, ['CrapsBattleFinalized'], { contract: 'CRAPS', filters: { battleKey: key }, fromBlock: start.blockNumber, signal })).at(-1);
  if (!final) throw new ChainDataError('This battle is still settling.', 'REPLAY_PENDING');
  // Reused day banks are read at the settlement block for historical replays.
  s = await s.client.snapshot({ blockTag: final.blockNumber, signal });
  const board = await crapsField(s, '_battles', key);
  const entrants = Number(board & 0xffffffffn); const resolved = Number((board >> 32n) & 0xffffffffn);
  if (!entrants || resolved !== entrants) throw new ChainDataError('The completed battle is missing its field.', 'INCOMPLETE_HISTORY');
  const { fromBlock } = custom ? { fromBlock: start.blockNumber } : await activityRange(s, day, signal);
  const events = await eventFacts(s, ['CrapsBonusArmed', 'CrapsBonusOpened', 'CrapsBattleFinalized', 'CrapsBattlePaid', 'CrapsBetSettled', 'CrapsHighRollerPaid', 'CrapsHighRollerDayOpened', 'CrapsProgressivePaid', 'CrapsProgressiveFunded',
    'JackpotBattleStarted'], { contract: 'CRAPS', fromBlock, toBlock: final.blockNumber, signal });
  const arms = events.filter(e => e.name === 'CrapsBonusArmed' && (custom ? e.args.battleKey === key : BigInt(e.args.slot) / 8n === slot / 8n));
  const dayN = custom ? 0 : Number((await crapsField(s, '_dayTickets', slot / 8n * 8n)) & 0xffffffffn);
  const windows = await Promise.all(arms.map(async e => {
    const count = Number((await crapsField(s, '_battles', e.args.battleKey)) & 0xffffffffn);
    return { battleKey: e.args.battleKey, slot: BigInt(e.args.slot), ownN: count - dayN, dayN, armedBlock: BigInt(e.blockNumber) };
  }));
  // The day's jackpot field walks the same day tickets (`CrapsBattle._dayField`; none on the detached
  // remainder 7), then its awarded seats, so any of its settlements in range must be attributable.
  if (!custom) windows.push(...await Promise.all(events.filter(e => e.name === 'JackpotBattleStarted' && BigInt(e.args.slot) / 8n === slot / 8n).map(async e => {
    const jSlot = BigInt(e.args.slot); const jKey = slotKey(jSlot);
    const count = Number((await crapsField(s, '_battles', jKey)) & 0xffffffffn);
    const jDayN = jSlot % 8n === 7n ? 0 : dayN; const drawn = Number(e.args.drawnEntries);
    return { battleKey: jKey, slot: jSlot, ownN: count - jDayN - drawn, dayN: jDayN, drawn, armedBlock: BigInt(e.blockNumber) };
  })));
  // Definite sibling markers identify a whole contiguous settlement run;
  // ambiguous day-only batches are resolved by the contract's dense cursor.
  const byTx = new Map();
  for (const e of events) { if (!byTx.has(e.transactionHash)) byTx.set(e.transactionHash, []); byTx.get(e.transactionHash).push(e); }
  const logs = [];
  for (const txRows of byTx.values()) {
    let hint = null;
    for (const e of [...txRows].reverse()) {
      if (['CrapsBattleFinalized', 'CrapsHighRollerPaid'].includes(e.name)) hint = e.args.battleKey;
      if (e.name !== 'CrapsBetSettled') continue;
      const id = BigInt(e.args.betId); const ownSlot = id >> 64n;
      if (!windows.some(w => w.slot === ownSlot) && (custom || ownSlot !== slot / 8n * 8n)) continue;
      logs.push({ ...e, betId: id, storedSlot: ownSlot, storedBattleKey: hint, blockNumber: BigInt(e.blockNumber) });
    }
  }
  const { attributeCrapsSettlements, crapsProgressiveCutoffs, jackpotHighExtra } = await loadCrapsProducer(s.client.chain.crapsReplayEngineVersion);
  const assigned = attributeCrapsSettlements(windows, logs, { requireCompleteFor: key }).byBattle.get(key);
  if (!assigned || assigned.length !== entrants) throw new ChainDataError('The settlement field is incomplete.', 'INCOMPLETE_HISTORY');
  const opened = events.find(e => e.name === 'CrapsBonusOpened' && e.args.battleKey === key);
  let terms, high, word;
  // Presentation travels with the mutable pointer; it is not part of the dice tape.
  // Finalized.pot includes the jackpot's remainder, which stake * entrants omits.
  const prize = { mainPotWei: String(final.args.pot), jackpotMultiplierBps: null, bonusMultiplier: null };
  const mainPaid = events.find(e => e.name === 'CrapsBattlePaid' && e.args.battleKey === key);
  // Finalized.pot is the whole pool, including other awards. Only the payout
  // event states what the main winner actually won.
  if (mainPaid) prize.mainPayoutWei = String(mainPaid.args.amount);
  // The replay engine takes the CHAIN'S OWN units (whole FLIP), as CrapsEngine.settleBattle does. Decoded FLIP event amounts arrive as token wei; this undoes that.
  const raw = value => flipToChain(BigInt(value));
  if (jackpot) {
    // `_slotWindow` on a jackpot slot: bankroll from the sealed round, a fixed 5x goal, a round of
    // bankroll × 2 / 5 (`_schedRound`), the bounty in 100-FLIP units; the high lane is the day's.
    // The sealed bankroll is already capped (41,943,000 FLIP), so no cap is re-derived here.
    const round = await crapsField(s, '_jackpotRounds', slot);
    if (!round.word || BigInt(round.word) !== BigInt(start.args.word)) throw new ChainDataError('The jackpot battle word is missing.', 'INCOMPLETE_HISTORY');
    word = BigInt(round.word);
    prize.jackpotMultiplierBps = Number(round.multiplierBps);
    terms = { bankroll: BigInt(round.bankroll), goal: BigInt(round.bankroll) * 5n, boardStake: BigInt(round.bankroll) * 2n / 5n, battleStake: BigInt(round.bountyUnits) * 100n * chainTokenUnit() };
    high = Number(events.find(e => e.name === 'CrapsHighRollerDayOpened' && Number(e.args.day) === day)?.args.multiplier ?? 0);
    // A jackpot high seat rides `bankroll + highExtra` of fee-funded capital (`_slotWindow`), not H copies.
    terms.highExtra = jackpotHighExtra(BigInt(high), BigInt(round.multiplierBps), crapsJackpotEntryPrice(round));
  } else if (custom) {
    const c = decodeCustomBattleTerms(await s.field('CRAPS', '_customBattle', slot));
    const played = c.played * chainTokenUnit(); const bankroll = played * c.bankMult;
    terms = { bankroll, goal: bankroll * c.goalMult, boardStake: played, battleStake: c.stakeUnits * 100n * chainTokenUnit() };
    high = c.highMultiple;
  } else {
    if (!opened || raw(opened.args.boardStake) % 7n) throw new ChainDataError('Missing battle terms.', 'INCOMPLETE_HISTORY');
    terms = { bankroll: raw(opened.args.bankroll), goal: raw(opened.args.goal), boardStake: raw(opened.args.boardStake) / 7n * 10n, battleStake: raw(opened.args.battleStake) };
    high = Number(events.find(e => e.name === 'CrapsHighRollerDayOpened' && Number(e.args.day) === day)?.args.multiplier ?? 0);
  }
  const seats = [];
  for (let offset = 0; offset < assigned.length; offset += 25) {
    checkAbort(signal);
    seats.push(...await Promise.all(assigned.slice(offset, offset + 25).map(async log => {
      const id = BigInt(log.betId); const header = await crapsBetWord(s, id);
      // A scheduled bank is reused 64 days later; the field's slips are gone from storage then.
      if (!header) throw new ChainDataError('This battle is too old to replay from current storage.', 'HISTORICAL_STATE_UNAVAILABLE');
      const playerId = Number(header & 0xffffffffn);
      const player = await walletAddressOf(s, playerId);
      if (player !== log.args.player) throw new ChainDataError('A replay seat owner disagrees with settlement.', 'INCOMPLETE_HISTORY');
      const lane = (id >> 64n) === slot ? 'window' : 'day'; const shift = lane === 'day' ? slot % 8n - 1n : 0n;
      const isHigh = Boolean((header >> (65n + shift)) & 1n);
      if (isHigh && high < 2) throw new ChainDataError('Missing high-roller multiplier.', 'INCOMPLETE_HISTORY');
      // An AWARDED jackpot seat carries its copies of the run above bit 224 and throws dice keyed
      // to its bet id (`CrapsEngine.settleBattle`); zero on every paid seat.
      const awardUnits = Number(header >> 72n);
      return { betId: id, player, playerId, chips: Number((header >> 32n) & 0x3fffffffn), standing: 0,
        multiple: isHigh ? high : 1, ...(awardUnits ? { awardUnits } : {}), lane, chainWon: raw(log.args.won), chainPaid: raw(log.args.paid) };
    })));
  }
  const paid = events.find(e => e.name === 'CrapsProgressivePaid' && e.args.battleKey === key);
  const pool = events.filter(e => e.args.balance != null && compareLogs(e, final) <= 0).at(-1);
  // Paid.balance is AFTER this battle's debit. The header shows the full pool
  // available to this battle, while progressive.amountWei retains its award.
  // Adding the actual debit back also preserves historical pass/liquid splits.
  const progressivePoolWei = paid ? BigInt(paid.args.balance) + BigInt(paid.args.paid)
    : pool ? BigInt(pool.args.balance) : null;
  prize.progressivePoolWei = progressivePoolWei?.toString() ?? null;
  const cuts = crapsProgressiveCutoffs(slot, terms.bankroll, terms.goal, terms.boardStake);
  const runtime = keccak256(await s.client.atBlock('eth_getCode', [s.client.address('CRAPS')], s, signal));
  if (s.client.chain.codeHashes?.CRAPS !== runtime) throw new ChainDataError('Craps runtime does not match the deployment manifest.', 'DEPLOYMENT_NOT_READY');
  if (!jackpot) word = await lootboxWord(s, arm.args.index, { fromBlock: arm.blockNumber, afterLogIndex: arm.logIndex, signal });
  if (!word) throw new ChainDataError('The settlement RNG word is missing.', 'INCOMPLETE_HISTORY');
  // An ordinary field's pot boost rung rides the pointer, so a replay opened without lobby context
  // still rolls the right rung (a jackpot field has its pool multiplier instead).
  if (!jackpot) prize.bonusMultiplier = Number(boostQuarterMultiple(key, word)) / 4;
  await s.verify(signal);
  // A jackpot field has its own word and pool multiplier, carried in prize above.
  // Index 0 marks that there is no ordinary lootbox boost to look up.
  return { battleKey: key, word, winnerSeat: Number(final.args.winnerId ?? 0), ruleset: { chainId: s.client.chain.id, contract: s.client.address('CRAPS'), runtimeCodeHash: runtime,
    engineVersion: s.client.chain.crapsReplayEngineVersion ?? 'unsupported-deployment' },
    settlement: { boundSlot: slot, boundIndex: jackpot ? 0n : BigInt(arm.args.index), finalizedBlock: BigInt(final.blockNumber), finalizedBlockHash: final.blockHash }, terms, seats, prize,
    progressive: { scoreBpsBefore: BigInt(paid?.args.scoreBps ?? final.args.winningScoreBps), thresholdScoreBps: BigInt(cuts?.common ?? 0),
      amountWei: paid ? raw(paid.args.candidate) : pool ? raw(pool.args.balance) : null, winnerBetId: paid ? BigInt(paid.args.betId) : null,
      wonAtScoreBps: paid ? Number(paid.args.scoreBps) : null, status: paid ? 'won' : 'not-awarded' }, publishedAt: new Date(s.block.timestamp * 1000).toISOString() };
}

/** Keep CPU work serial, without parking other battles behind an unrelated RPC read. */
export function buildCrapsReplayInWorker(input) {
  const job = workerTail.then(() => new Promise((resolve, reject) => {
    if (typeof Worker === 'undefined') throw new ChainDataError('Replay construction needs browser worker support.');
    const worker = new Worker(new URL('./craps-worker.js?v=final-ranks-20261010', import.meta.url), { type: 'module' });
    const finish = (error, bundle) => {
      clearTimeout(timer);
      worker.terminate();
      error ? reject(error) : resolve(bundle);
    };
    const timer = setTimeout(() => finish(new ChainDataError('The battle replay took too long. Try again.', 'REPLAY_TIMEOUT')), CRAPS_REPLAY_WORKER_TIMEOUT_MS);
    worker.onmessage = ({ data }) => finish(data.error ? new ChainDataError(data.error, 'REPLAY_MISMATCH') : null, data);
    worker.onerror = event => finish(new ChainDataError(event.message || 'Battle replay worker failed.'));
    try { worker.postMessage(input); } catch (error) { finish(error); }
  }));
  // A failed or timed-out worker must release the next battle too.
  workerTail = job.catch(() => {});
  return job;
}

async function buildReplay(client, key) {
  const s = await client.snapshot({ fresh: true }); const input = await loadReplayInputs(s, key);
  const bundle = await buildCrapsReplayInWorker(input);
  await s.verify();
  const { buildCrapsReplayPointer } = await loadCrapsProducer(s.client.chain.crapsReplayEngineVersion);
  return { finalizedBlock: input.settlement.finalizedBlock, finalizedHash: input.settlement.finalizedBlockHash, files: new Map(bundle.files.map(file => [file.path, file.body])), pointer: { ...buildCrapsReplayPointer({
    battleKey: key, deployment: input.ruleset, status: 'ready', entrants: bundle.entrants, resolved: bundle.entrants,
    finalizedBlock: input.settlement.finalizedBlock, publishedAt: input.publishedAt, digest: bundle.digest }), prize: input.prize, rankings: bundle.rankings } };
}
export async function chainReplayFetch(path, { signal, client = chainClient() } = {}) {
  checkAbort(signal);
  const url = new URL(path, 'https://local.invalid');
  const match = url.pathname.match(/\/battles\/(0x[0-9a-f]{64})\/(latest\.json|results\/.*)$/i);
  if (!match) return new Response('Unknown replay path', { status: 404 });
  const key = battleKey(match[1]); const cacheKey = `${client.chain.id}:${client.address('CRAPS')}:${key}`;
  let job = jobs.get(cacheKey);
  if (job?.result && (await client.header(job.result.finalizedBlock, signal)).hash !== job.result.finalizedHash) {
    jobs.delete(cacheKey); job = null;
  }
  if (!job || job.error && Date.now() - job.at > 15_000) {
    job = { at: Date.now() }; jobs.set(cacheKey, job);
    // Fetch independent battles immediately. Only their CPU workers share a queue.
    job.promise = buildReplay(client, key)
      .then(value => { job.result = value; }).catch(error => { job.error = error; }).finally(() => {
        job.promise = null;
        for (const [oldKey, old] of jobs) if (jobs.size > 2 && oldKey !== cacheKey && !old.promise) jobs.delete(oldKey);
      });
  }
  // Wait for the build rather than answer with a placeholder: a 0-entrant "pending" pointer
  // read as a real settlement state, and the open paths show it once and never ask again.
  if (job.promise) {
    await new Promise((resolve, reject) => {
      const abort = () => reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
      if (signal?.aborted) return abort();
      signal?.addEventListener('abort', abort, { once: true });
      job.promise.then(resolve, resolve).finally(() => signal?.removeEventListener('abort', abort));
    });
  }
  checkAbort(signal);
  if (match[2] !== 'latest.json') {
    const body = job.result?.files.get(url.pathname);
    return body ? new Response(body, { headers: { 'content-type': 'application/json' } }) : new Response('Replay is still being reconstructed', { status: 503 });
  }
  const pointer = job.result?.pointer ?? { schemaVersion: 1, kind: 'craps-replay-pointer', battleKey: key,
    status: job.error && job.error.code !== 'REPLAY_PENDING' ? 'failed' : 'pending', entrants: job.error?.entrants ?? 0, resolved: job.error?.resolved ?? 0,
    finalizedBlock: null, publishedAt: new Date().toISOString(), error: job.error && job.error.code !== 'REPLAY_PENDING' ? job.error.message : null, digest: null, manifestPath: null };
  return new Response(JSON.stringify(pointer), { headers: { 'content-type': 'application/json' } });
}
